const score=(pressurizedPods,vacuumPods,dockingArms,solarFlare)=>{
  const payloadTally=pressurizedPods+vacuumPods;
  const effort=pressurizedPods*8+vacuumPods*14+(solarFlare ? dockingArms*5 : 0);
  const allowance=dockingArms*47;
  const approved=Math.min(effort,allowance);
  const spillover=Math.max(effort-allowance,0);
  const orbitPasses=Math.ceil(payloadTally/4);
  return approved+spillover*7+orbitPasses*6;
};
export async function loadParley(){return {orbital_clearance_rating:(...args)=>BigInt(score(...args))}}
